208	    for (const change of plan.schemaChanges.entityTypes) {
209	      if (change.action === 'add type') candidate.entityTypes[change.id] = JSON.parse(JSON.stringify(change.definition));
210	      else {
211	        const type = candidate.entityTypes[change.id];
212	        type.fields = [...(type.fields || []), ...JSON.parse(JSON.stringify(change.fields))];
213	        type.associations = [...(type.associations || []), ...JSON.parse(JSON.stringify(change.associations))];
