 50	    byEmail: { id: 'byEmail', type: 'person', name: 'Alex E', email: 'ALEX@example.com' },
 51	    byAccount: { id: 'byAccount', type: 'person', name: 'Alex Account', accountName: 'alex', domain: 'acme' },
 52	    byName: { id: 'byName', type: 'person', name: 'Alex Example' }
