 63	  assert.ok(serialPreview.some(field => field.field === 'id' && field.disposition === 'retained'));
 64	  assert.equal(plan.person.status, 'conflict');
 65	  assert.deepEqual(plan.person.candidates.map(x => x.id), ['byEmail', 'byAccount']);
 66	  assert.equal(plan.person.candidates.some(x => x.id === 'byName'), false, 'name-only must never match');
